pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Bound caller to avoid address(0) issues (not strictly needed)
        vm.assume(caller != address(0));
        // Seed the market first so initialized becomes true
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);
        // Verify initialized is true before calling DrugDealer
        assertTrue(c.initialized());
        // Now call DrugDealer from the fuzzed address
        vm.prank(caller);
        c.DrugDealer();
        // The rule: initialized must still be true after DrugDealer returns
        assertTrue(c.initialized());
    }
}

