pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref, uint256 ethAmount, uint256 drugsAmount) public {
        vm.assume(caller != address(0) && ref != address(0) && caller != ref);
        vm.assume(drugsAmount <= 1000000);
        vm.assume(ethAmount <= 100 ether);

        // Seed the market first
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("seedMarket(uint256)", 100));
        if (!success) return;

        // Give caller some kilos
        vm.prank(caller);
        c.getFreeKilo();

        // Get initial kilos
        uint256 initialKilos = c.Kilos(caller);

        // Buy some drugs for the caller to have claims
        vm.deal(caller, ethAmount);
        vm.prank(caller);
        (success, ) = address(c).call{value: ethAmount}(abi.encodeWithSignature("buyDrugs()"));

        // Record state before collectDrugs
        uint256 kilosBefore = c.Kilos(caller);
        uint256 drugsBefore = c.getMyDrugs();

        // Call collectDrugs
        vm.prank(caller);
        c.collectDrugs(ref);

        // Check that kilos increased by at least the new kilos produced from drugs
        uint256 kilosAfter = c.Kilos(caller);
        uint256 drugsUsed = drugsBefore;
        uint256 expectedNewKilos = drugsUsed / 86400;

        // In reference, kilos after = kilos before + newKilo (since Kilos[caller] is added to)
        // In mutant, kilos after = 0 + newKilo (because Kilos[caller] is reset to 0 first)
        // So the rule: kilosAfter >= kilosBefore is true for reference but may fail for mutant
        assertTrue(kilosAfter >= kilosBefore, "Kilos should not decrease after collectDrugs");
    }
}

