        // Since DrugDealer can only be called by CEO, we must test with CEO caller.
        vm.prank(c.ceoAddress());
        c.DrugDealer();

        // Now, the caller's Kilos should be STARTING_KILOS if they had zero before.
        // Because the original getFreeKilo gives STARTING_KILOS, but buggy version does not.
