pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
    }

    function testFuzz_property(address caller, address other) public {
        // Ensure caller is not zero address
        vm.assume(caller != address(0));
        vm.assume(other != address(0));
        vm.assume(caller != other);

        // Initialize the market
        c.seedMarket(1000);

        // Give some ETH to caller so they can call buyDrugs (optional, not needed for property)
        vm.deal(caller, 1 ether);

        // Pre-call state: we need to know total Kilos (sum over all addresses). We can only read caller's and other's Kilos via public getter.
        uint256 preCallerKilos = c.getMyKilo(); // this reads Kilos[address(this)], not caller's! 
        // Actually getMyKilo() is for msg.sender. To read arbitrary address, we must use the public mapping getter.
        uint256 preCallerKilos2 = c.Kilos(caller);
        uint256 preOtherKilos = c.Kilos(other);

        // Perform DrugDealer() call as caller
        vm.prank(caller);
        c.DrugDealer();

        // Post-call state
        uint256 postCallerKilos = c.Kilos(caller);
        uint256 postOtherKilos = c.Kilos(other);

        // The property: for the caller, Kilos should not change (no collectDrugs/sellDrugs called)
        assertTrue(preCallerKilos2 == postCallerKilos, "Caller's Kilos changed after DrugDealer()");
        // For the other, Kilos should not change
        assertTrue(preOtherKilos == postOtherKilos, "Other's Kilos changed after DrugDealer()");
    }
}

