        vm.deal(user, amount);
        vm.prank(user);
        c.buyDrugs{value: amount}();

        uint256 newClaimed = c.claimedDrugs(user);

        // Calculate expected drugsBought with dev fee deducted
        uint256 contractBalanceBefore = address(c).balance - amount;
        uint256 drugsBought = c.calculateDrugBuy(amount, contractBalanceBefore);
        uint256 feeDev = c.devFee(drugsBought);
        uint256 expectedDrugs = drugsBought - feeDev;

        // The general rule: newClaimed = oldClaimed + expectedDrugs
        assertTrue(newClaimed == oldClaimed + expectedDrugs, "claimedDrugs should reflect dev fee deduction");
    }
}

