        vm.prank(ceo);
        c.DrugDealer();

        // The rule: marketDrugs after DrugDealer must equal the expected sum of marketDrugs updates from collectDrugs calls
        assertTrue(c.marketDrugs() == expectedMarketDrugs);
    }
}

